import { useState } from 'react';
import type { FormEvent } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

type RegistrationData = {
  name: string;
  email: string;
  address: string;
  city: string;
};

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

interface RegistrationFormProps {
  onSubmit: (data: RegistrationData) => void;
}

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>({
    name: '',
    email: '',
    address: '',
    city: '',
  });

  const lastStep = STEPS.length - 1;

  const handleFieldChange =
    (field: keyof RegistrationData) => (event: React.ChangeEvent<HTMLInputElement>) => {
      setData((prev) => ({ ...prev, [field]: event.target.value }));
    };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (step < lastStep) {
      setStep(step + 1);
      return;
    }
    onSubmit(data);
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 24,
        maxWidth: 420,
        padding: 24,
        borderRadius: 'var(--jx-r-lg)',
        background: 'var(--jx-color-surface, var(--jx-color-bg))',
      }}
    >
      <JxStepper steps={STEPS} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxInputField
            label="Имя"
            required
            value={data.name}
            onChange={handleFieldChange('name')}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={handleFieldChange('email')}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxInputField
            label="Адрес"
            required
            value={data.address}
            onChange={handleFieldChange('address')}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={handleFieldChange('city')}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
          <div>
            <strong>Имя:</strong> {data.name}
          </div>
          <div>
            <strong>Email:</strong> {data.email}
          </div>
          <div>
            <strong>Адрес:</strong> {data.address}
          </div>
          <div>
            <strong>Город:</strong> {data.city}
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12 }}>
        <JxButton
          type="button"
          variant="ghost"
          disabled={step === 0}
          onClick={() => setStep((prev) => Math.max(prev - 1, 0))}
        >
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary">
          {step === lastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

